try{$db->query("CREATE TABLE `{$p}fm2_migration_quarantine_registry`(id BIGINT PRIMARY KEY,source_system VARCHAR(40),source_locator VARCHAR(80),source_cutoff_at DATETIME,source_digest CHAR(64),classification_version VARCHAR(80),category VARCHAR(40),reason_codes_json TEXT,quarantine_codes_json TEXT,first_seen_at VARCHAR(40))");$db->query("CREATE TABLE `{$p}fm2_migration_quarantine_observations`(id BIGINT PRIMARY KEY,registry_id BIGINT,run_id CHAR(36),observed_at VARCHAR(40))");for($i=1;$i<=30;$i++){$locator='hmac-sha256:'.hash('sha256','locator-'.$i);$digest=hash('sha256','source-'.$i);$category=$i%2?'legacy_historical':'legacy_active';$code=$i%2?'COMPLETION_WITHOUT_START_EVIDENCE':'MALFORMED_EVENT_DATE';$db->query("INSERT INTO `{$p}fm2_migration_quarantine_registry` VALUES({$i},'legacy_fmonitor','{$locator}','2026-08-30 23:59:59','{$digest}','legacy-object-classification-v1','{$category}','[\"PTO_ACT_RECORDED\"]','[\"{$code}\"]','2026-08-30T23:59:59+03:00')");$db->query("INSERT INTO `{$p}fm2_migration_quarantine_observations` VALUES({$i},{$i},'44444444-4444-4444-8444-444444444444','2026-08-30T23:59:59+03:00')");}$model=(new MigrationQuarantineReadModel($db,$p))->read(['category'=>'legacy_historical','code'=>'COMPLETION_WITHOUT_START_EVIDENCE'],1);quarantineReadCheck($model['total']===15&&count($model['rows'])===15,'deterministic filters failed');$row=$model['rows'][0];quarantineReadCheck(preg_match('/^Q-[A-F0-9]{12}$/D',$row['reference'])===1&&$row['observationCount']===1&&$row['status']==='observed'&&$row['runReference']==='RUN-'.strtoupper(substr(hash('sha256','44444444-4444-4444-8444-444444444444'),0,10)),'redacted observation projection failed');$all=(new MigrationQuarantineReadModel($db,$p))->read([],1);quarantineReadCheck(count($all['rows'])===25&&$all['pages']===2,'bounded pagination failed');echo"PASS migration quarantine read model\n";}finally{$db->query("DROP TABLE IF EXISTS `{$p}fm2_migration_quarantine_observations`");$db->query("DROP TABLE IF EXISTS `{$